27	/// blocking write
28	ssize_t write_data(int fd, const void *buf, size_t count)
29	{
30	    for (size_t n = 0; n < count;)
31	    {
32	        ssize_t sz = write(fd, reinterpret_cast<const char*>(buf) + n, count - n);
33	        if (sz < 0)
34	        {
35	            if (errno == EINTR)
36	                continue;
37	            return sz;
38	        }
39	        n += sz;
40	    }
41	    return count;
42	}
