44	/// blocking read
45	ssize_t read_data(int fd, void *buf, size_t count)
46	{
47	    for (size_t n = 0; n < count;)
48	    {
49	        ssize_t sz = read(fd, reinterpret_cast<char*>(buf) + n, count - n);
50	        if (sz < 0)
51	        {
52	            if (errno == EINTR)
53	                continue;
54	            return sz;
55	        }
56	        if (sz == 0)
57	            return count - n;
58	        n += sz;
59	    }
60	    return count;
61	}
