63	/// Main compression part
64	int doCompress(char * input, char * output, off_t & in_offset, off_t & out_offset,
65	               off_t input_size, off_t output_size, ZSTD_CCtx * cctx)
66	{
67	    size_t compressed_size = ZSTD_compress2(cctx, output + out_offset, output_size, input + in_offset, input_size);
68	    if (ZSTD_isError(compressed_size))
69	    {
70	        std::cerr << "Error (ZSTD): " << compressed_size << " " << ZSTD_getErrorName(compressed_size) << std::endl;
71	        return 1;
72	    }
73	    in_offset += input_size;
74	    out_offset += compressed_size;
75	    return 0;
76	}
