180	/// Save Metadata at the end of file
181	int saveMetaData(char* filenames[], int count, int output_fd, const MetaData& metadata,
182	                 FileData* files_data, size_t pointer, size_t sum_file_size)
183	{
184	    /// Allocate memory for metadata
185	    if (0 != ftruncate(output_fd, pointer + count * sizeof(FileData) + sum_file_size + sizeof(MetaData)))
186	    {
187	        perror(nullptr);
188	        return 1;
189	    }
190	
191	    char * output = static_cast<char*>(
192	        mmap(nullptr,
193	            pointer + count * sizeof(FileData) + sum_file_size + sizeof(MetaData),
194	            PROT_READ | PROT_WRITE, MAP_SHARED,
195	            output_fd,
196	            0)
197	        );
198	    if (output == MAP_FAILED)
199	    {
200	        perror(nullptr);
201	        return 1;
202	    }
203	
204	    /// save information about files and their names
205	    for (int i = 0; i < count; ++i)
206	    {
207	        /// Save file data
208	        memcpy(output + pointer, reinterpret_cast<char*>(files_data + i), sizeof(FileData));
209	        pointer += sizeof(FileData);
210	
211	        /// Save file name
212	        memcpy(output + pointer, filenames[i], files_data[i].name_length);
213	        pointer += files_data[i].name_length;
214	    }
215	
216	    /// Save metadata
217	    memcpy(output + pointer, reinterpret_cast<const char*>(&metadata), sizeof(MetaData));
218	    return 0;
219	}
