339	int copy_decompressor_self(const char *self, int output_fd)
340	{
341	    int input_fd = open(self, O_RDONLY);
342	    if (input_fd == -1)
343	    {
344	        perror(nullptr);
345	        return 1;
346	    }
347	
348	    if (-1 == lseek(input_fd, -15, SEEK_END))
349	    {
350	        perror(nullptr);
351	        close(input_fd);
352	        return 1;
353	    }
354	
355	    char size_str[16] = {0};
356	    if (ssize_t sz = read_data(input_fd, size_str, 15); sz < 15)
357	    {
358	        if (sz < 0)
359	            perror(nullptr);
360	        else
361	            std::cerr << "Error: unable to extract decompressor" << std::endl;
362	        close(input_fd);
363	        return 1;
364	    }
365	
366	    int decompressor_size = atoi(size_str);
367	
368	    if (-1 == lseek(input_fd, -(decompressor_size + 15), SEEK_END))
369	    {
370	        perror(nullptr);
371	        close(input_fd);
372	        return 1;
373	    }
374	
375	    int ret = copy_decompressor(input_fd, decompressor_size, output_fd);
376	    close(input_fd);
377	    return ret;
378	}
