43	/// decompress data from in_fd into out_fd
44	int decompress(char * input, char * output, off_t start, off_t end, size_t max_number_of_forks=10)
45	{
46	    off_t in_pointer = start, out_pointer = 0;
47	    off_t size = 0;
48	    off_t max_block_size = 1ull<<27;
49	    off_t decompressed_size = 0;
50	    size_t number_of_forks = 0;
51	
52	    /// Create context
53	    ZSTD_DCtx * dctx = ZSTD_createDCtx();
54	    if (dctx == nullptr)
55	    {
56	        std::cerr << "Error (ZSTD): failed to create decompression context" << std::endl;
57	        return 1;
58	    }
59	    pid_t pid;
60	    bool error_happened = false;
61	
62	    /// Decompress data
63	    while (in_pointer < end && !error_happened)
64	    {
65	        size = ZSTD_findFrameCompressedSize(input + in_pointer, max_block_size);
66	        if (ZSTD_isError(size))
67	        {
68	            std::cerr << "Error (ZSTD): " << size << " " << ZSTD_getErrorName(size) << std::endl;
69	            error_happened = true;
70	            break;
71	        }
72	
73	        decompressed_size = ZSTD_getFrameContentSize(input + in_pointer, max_block_size);
74	        if (ZSTD_isError(decompressed_size))
75	        {
76	            std::cerr << "Error (ZSTD): " << decompressed_size << " " << ZSTD_getErrorName(decompressed_size) << std::endl;
77	            error_happened = true;
78	            break;
79	        }
80	
81	        pid = fork();
82	        if (-1 == pid)
83	        {
84	            perror(nullptr);
85	            /// If fork failed just decompress data in main process.
86	            if (0 != doDecompress(input, output, in_pointer, out_pointer, size, decompressed_size, dctx))
87	            {
88	                error_happened = true;
89	                break;
90	            }
91	            in_pointer += size;
92	            out_pointer += decompressed_size;
93	        }
94	        else if (pid == 0)
95	        {
96	            /// Decompress data in child process.
97	            if (0 != doDecompress(input, output, in_pointer, out_pointer, size, decompressed_size, dctx))
98	                exit(1);
99	            exit(0);
100	        }
101	        else
102	        {
103	            ++number_of_forks;
104	            while (number_of_forks >= max_number_of_forks)
105	            {
106	                /// Wait any fork
107	                int status;
108	                waitpid(0, &status, 0);
109	
110	                /// If error happened, stop processing
111	                if (WEXITSTATUS(status) != 0)
112	                {
113	                    error_happened = true;
114	                    break;
115	                }
116	
117	                --number_of_forks;
118	            }
119	            in_pointer += size;
120	            out_pointer += decompressed_size;
121	        }
122	    }
123	
124	    /// wait for all working decompressions
125	    while (number_of_forks > 0)
126	    {
127	        /// Wait any fork
128	        int status;
129	        waitpid(0, &status, 0);
130	
131	        if (WIFEXITED(status))
132	        {
133	            if (WEXITSTATUS(status) != 0)
134	                error_happened = true;
135	        }
136	        else
137	        {
138	            error_happened = true;
139	            if (WIFSIGNALED(status))
140	            {
141	                if (WCOREDUMP(status))
142	                    std::cerr << "Error: child process core dumped with signal " << WTERMSIG(status) << std::endl;
143	                else
144	                    std::cerr << "Error: child process was terminated with signal " << WTERMSIG(status) << std::endl;
145	            }
146	        }
147	
148	        if (WEXITSTATUS(status) != 0)
149	            error_happened = true;
150	
151	        --number_of_forks;
152	    }
153	
154	    /// If error happen end of processed part will not reach end
155	    if (in_pointer < end || error_happened)
156	        return 1;
157	
158	    return 0;
159	}
